/* @prim:begin 27-section-label */
.section-label { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); margin-bottom: 10px; }
/* @prim:end 27-section-label */
/* @prim:begin 31-callout */
.section-label { font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); margin-bottom: 10px; }
.callout { max-width: var(--measure, 640px); background: var(--gold-bg); border: 1px solid var(--gold); border-radius: var(--ds-r-sm); padding: 12px 16px; color: var(--text-secondary); }
.callout.red { background: var(--red-bg); border-color: var(--red); }
.callout b { font-family: var(--ds-font-mono); font-size: var(--fs-label); letter-spacing: 0.1em; text-transform: uppercase; color: var(--gold); margin-right: 6px; }
.callout.red b { color: var(--red); }
/* @prim:end 31-callout */
/* @prim:begin 53-cold-read */
.cr { display: flex; flex-direction: column; gap: 20px; }
.cr > * { margin: 0; }
.cr > .callout { max-width: none; }
.cr > .callout.cr-read { background: var(--surface-2); border-color: var(--border); }
.cr > .callout.cr-read b { color: var(--text-secondary); }
.cr-slots { margin: 0; display: grid; grid-template-columns: max-content minmax(0, 1fr); column-gap: 0; }
.cr-slots dt, .cr-slots dd { margin: 0; padding: 12px 0; border-top: 1px solid var(--border); }
.cr-slots dt:first-of-type, .cr-slots dt:first-of-type + dd { border-top: 0; padding-top: 0; }
.cr-slots dt.section-label { margin: 0; padding-right: 28px; line-height: 1.6rem; }
.cr-slots dd { font-size: var(--fs-body); line-height: 1.6; color: var(--text); }
.cr-how { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin: 0; padding: 0; list-style: none; }
.cr-step { position: relative; display: flex; flex-direction: column; gap: 8px; padding: 16px; border: 1px solid var(--border); border-radius: var(--ds-r-sm); background: var(--surface); }
.cr-step > * { margin: 0; }
.cr-step .section-label { margin: 0; }
.cr-when { font-size: var(--fs-body); font-weight: 600; line-height: 1.4; color: var(--text); }
.cr-what { font-size: var(--fs-body); line-height: 1.5; color: var(--text); }
@media (max-width: 599px) { .cr-slots { grid-template-columns: minmax(0, 1fr); } .cr-slots dd { border-top: 0; padding-top: 2px; } .cr-slots dt { padding-right: 0; padding-bottom: 0; line-height: 1.4; } .cr-how { grid-template-columns: minmax(0, 1fr); } }
/* @prim:end 53-cold-read */

demo:
function cr(slots,how,read){var w=document.createElement('div');w.className='cr';
w.innerHTML='<dl class="cr-slots">'+slots.map(function(s){return '<dt class="section-label">'+s[0]+'</dt><dd>'+s[1]+'</dd>'}).join('')+'</dl>'
+(how.length?'<ol class="cr-how" aria-label="How">'+how.map(function(h){return '<li class="cr-step"><p class="section-label">'+h[0]+'</p><p class="cr-when">'+h[1]+'</p><p class="cr-what">'+h[2]+'</p></li>'}).join('')+'</ol>':'')
+(read?'<p class="callout cr-read"><b>How to read</b>'+read+'</p>':'');return w}
var S=[['Who','The person, in one line.'],['What','The thing, in the reader’s terms.'],['Where','Remote, or a place.'],['When','Now, and why now.'],['Why','The reason the work exists.']];
var H=[['Before','Today','This page.'],['During','Not booked yet','A 30-minute call at a time that suits you.'],['After','Within two days','The plan, reshaped with you.']];
document.querySelector('[data-stage]').appendChild(cr(S,H,'The overview first, then one tab per option.'));
document.querySelectorAll('[data-state]').forEach(function(el,i){var a=STATES[i];el.appendChild(cr(S.slice(0,a[0]),a[1]?H:[],a[2]?'One line on how to read the page.':''))});
